// ---------- ACD Users ----------
export const ACD_USERS = EMPLOYEES.map((e, i) => {
  const [first, ...rest] = e.name.split(' ');
  const teams = ['DWCS_ITHD_L1_LATAM', 'DWCS_ITHD_L1_NAM', 'DWCS_ITHD_L1_Firmwide', 'DWCS_ITHD_L1_HT_Markets', 'DWCS_ITHD_IAM', 'DWCS_ITHD_L2_VIP'];
  return {
    id: String(69600000 + i * 3911 + 7510),
    first,
    last: rest.join(' '),
    username: e.username,
    email: `${e.name.toLowerCase().replace(/[^a-z ]/g, '').split(' ').join('.')}@citi.com`,
    team: teams[i % teams.length],
    status: 'Active',
  };
});

